candidates.raw:
    if ((samples == NULL) || (weights == NULL) || (direction == NULL) || (resultant == NULL)) {
        return ADCS_E_NULL;
    }

    // Initialize outputs to zero for potential failure cases
    direction->x = 0.0;
    direction->y = 0.0;
    direction->z = 0.0;
    *resultant = 0.0;

    if (count < 2U || count > 32U) {
        return ADCS_E_RANGE;
    }

    adcs_vec3_t s = {0.0, 0.0, 0.0};
    double total_weight = 0.0;
    adcs_vec3_t u;
    size_t i;

    for (i = 0; i < count; i++) {
        if ((!isfinite(weights[i])) || (weights[i] <= 0.0)) {
            return ADCS_E_RANGE;
        }

        if (!adcs_is_finite_vec3(&samples[i])) {
            return ADCS_E_RANGE;
        }

        if (adcs_vec3_normalize(&samples[i], ADCS_EPS_NORM, &u) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        adcs_vec3_t weighted_u = adcs_vec3_scale(&u, weights[i]);
        s = adcs_vec3_add(&s, &weighted_u);
        total_weight += weights[i];
    }

    double norm_s = adcs_vec3_norm(&s);

    if (norm_s <= ADCS_EPS_COLLINEAR) {
        return ADCS_E_DEGENERATE;
    }

    // Normalize s to get direction
    double inv_norm_s = 1.0 / norm_s;
    direction->x = s.x * inv_norm_s;
    direction->y = s.y * inv_norm_s;
    direction->z = s.z * inv_norm_s;

    // Resultant magnitude divided by total weight
    *resultant = norm_s / total_weight;

    return ADCS_OK;
}

